facilityFormItem.onClickEventHandler:
          
  var initiatorId = functions.getValues().Initiator;
  var vacationStartDate = functions.getValues().BeginDateShift;
  var vacationEndDate = functions.getValues().EndDateShift;
  
  if (!initiatorId || !vacationStartDate || !vacationEndDate) {
    ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.FACILITIES_NN_SUBSTITUTION_SETUP_ERROR_MISSING_DATA'), 'warning', true);
    return;
  }
  
  functions.setIsItemHidden('ShowSubstitutesButton', false);
  functions.setIsItemHidden('SubstitutionsInfoBlock', true);
  
  window.prepareSubstitutionParameters();
  
  var substituteIdsString = functions.getValues().SubstituteIdsString;
  var systemIdsString = functions.getValues().SystemIdsString;
  var startDatesString = functions.getValues().StartDatesString;
  var endDatesString = functions.getValues().EndDatesString;
  
  ESS.actions.facilityActions.runFacility(
    {
      id: '2a5f2cfc-8646-4bb8-920c-a985b15da804' 
    },
    {
      parameters: {
        InitiatorId: initiatorId,
        VacationStartDate: vacationStartDate,
        VacationEndDate: vacationEndDate,
        SubstituteIdsString: substituteIdsString,
        SystemIdsString: systemIdsString,
        StartDatesString: startDatesString,
        EndDatesString: endDatesString
      }
    }
  );

facility.openingEventHandler:
  if (window.isFacilityRunning ?? false) {
    reject();
  }
  else {
    window.isFacilityRunning = true;
    ESS.network.sendRequest(`/api/functions/GetInitiatorId`)
    .then(function (initiatorId){
      ESS.network.sendRequest(`/api/functions/GetEmployeeCertificates`)																																			
      .then(function (certs) {
        if (certs.length == 0) {
          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SENDSTATEMENT_NO_CERTIFICATES_ERROR'));
          reject();
        } 
        else {
          ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
          .then(function (employee){
            ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned`)
            .then(function (isConsentSigned) {
              if (isConsentSigned != true && employee.positions.length == 1) {
                ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTVACATION_CONSENT_ERROR'));
                reject();
              }
              else {
                ESS.network.sendRequest(`/api/functions/GetVacationRecallStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false&isVacationRecall=true&isAuthorManager=false`)																																																		
                .then(function (VacationStatementData) {
                  if (VacationStatementData.Error.length == 0) {
                    if (employee.positions.length == 1) {
                      functions.setValue('Initiator', initiatorId);
                    }

                    var templateId = JSON.parse(VacationStatementData.TemplateId);
                    var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
                    functions.setValue('TemplateId', templateId);
                    functions.setValue('DocumentKindId', docKindId);
                    
                    functions.setIsItemHidden('DayCountCompensation', true);
                    
                    resolve();
                  } 
                  else {
                    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
                  }
                })
                .catch(function (error) {
                  ESS.toasts.showToast(error.message, 'danger', false);
                });
              }
            });
          });
        }
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, 'danger', false);
      });
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, 'danger', false);
    });
  }

facility.openedEventHandler:
    
      var initiatorId = functions.getValues().Initiator;
      ESS.network.sendRequest(`/api/functions/GetPartTimeEmployeesInfo?employeeId=${initiatorId}`)
      .then(function (info) {
        if (info){
          ESS.toasts.hideToast(window.partTimeEmployeesInfo);
          info = ESS.L('@HRPROVACATIONS.FACILITIES_NNSELFRECALLVACATIONEMPLOYEE_PARTTIMEEMPLOYEES_WARNING') + '\r\n' + info;
          window.partTimeEmployeesInfo = ESS.toasts.showToast(info, 'warning', false);
        }
      });

      ESS.network.sendRequest(`/api/functions/GetCurrentVacationForRecall?employeeId=${initiatorId}`)
      .then(function (vacationData){
        if (!vacationData.ErrorText || vacationData.ErrorText.length == 0) {
          functions.setValue('CurrentVacationData', JSON.stringify(vacationData.CurrentVacations));
          functions.setValue('CurrentVacation', vacationData.VacationPeriod);
          functions.setValue('VacationTypeCurrent', vacationData.VacationTypeId);
          functions.setValue('BeginDateCurrent', vacationData.CurrentDateStart);
          functions.setValue('EndDateCurrent', vacationData.CurrentDateEnd);
          functions.setValue('DurationCurrent', vacationData.DayCount);
        }
        else {
          window.errorOpened = functions.showError(vacationData.ErrorText, undefined, ESS.enums.FormErrorType.UNSPECIFIED);
        }
      });

      window.setDurationRecall = function () {
        var initiatorId = functions.getValues().Initiator;
        var beginDate = functions.getValues().BeginDateRecall;
        var endDate = functions.getValues().EndDateRecall;
        var currentVacationData = functions.getValues().CurrentVacationData;
        if (beginDate != null && endDate != null) {
          var url = `/api/functions/RecallDurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`
          ESS.network.sendRequest(url)
          .then(function (newDurationValue) {
            functions.setValue('DurationRecall', newDurationValue);
          });
        }
      }

      window.setDurationShift = function (rowIndex) {
        var initiatorId = functions.getValues().Initiator;
        var beginDateRecall = functions.getValues().BeginDateRecall;
        var endDateRecall = functions.getValues().EndDateRecall;
        var beginDateShift = functions.getValues().BeginDateShift;
        var endDateShift = functions.getValues().EndDateShift;
        var currentVacationData = functions.getValues().CurrentVacationData;
        if (beginDateRecall != null && endDateRecall != null && beginDateShift != null && endDateShift != null) {
          var url = `/api/functions/ShiftDurationInCalendarDaysWithoutHoliday?beginDateRecall=${beginDateRecall}&endDateRecall=${endDateRecall}&beginDateShift=${beginDateShift}&endDateShift=${endDateShift}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`
          ESS.network.sendRequest(url)
          .then(function (newDurationValue) {
            functions.setValue('DurationShift', newDurationValue);
          });
        }
      }

      window.setDayCountCompensation = function () {
        var isCompensation = functions.getValues().CompensationKind == "1";
        if (isCompensation) {
          var initiatorId = functions.getValues().Initiator;
          var beginDateRecall = functions.getValues().BeginDateRecall;
          var endDateRecall = functions.getValues().EndDateRecall;
          var durationRecall = functions.getValues().DurationRecall;
          var durationShift = functions.getValues().DurationShift;
          var currentVacationData = functions.getValues().CurrentVacationData;
          var url = `/api/functions/GetDayCountCompensation?beginRecall=${beginDateRecall}&endRecall=${endDateRecall}&durationRecall=${durationRecall}&durationShift=${durationShift}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`
          ESS.network.sendRequest(url)
          .then(function (dayCountCompensation) {
            functions.setValue('DayCountCompensation', dayCountCompensation);
          });
        }
      }

      window.checkDurationShift = function () {
        var durationRecall = +functions.getValues().DurationRecall;
        var durationShift = +functions.getValues().DurationShift;
        functions.removeError(window.errorDurationShift);
        if (durationShift > 0 && durationRecall > 0) {
          if (durationShift > durationRecall) {
            window.errorDurationShift = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_NNSELFRECALLVACATIONEMPLOYEE_LIMITDAYSSHIFT_ERROR'));
          }
        }
      }

      window.checkDurationRecall = function (formItem) {
        var endDateRecall = new Date(formItem.value).setHours(0, 0, 0, 0);
        var beginDateCurrent = new Date(functions.getValues().BeginDateCurrent).setHours(0, 0, 0, 0);
        var endDateCurrent = new Date(functions.getValues().EndDateCurrent).setHours(0, 0, 0, 0);
        functions.removeError(window[`error${formItem.name}`]);
        if (endDateRecall < beginDateCurrent || endDateRecall > endDateCurrent) {
         window[`error${formItem.name}`] = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_NNSELFRECALLVACATIONEMPLOYEE_DATERECALL_ERROR'), undefined, ESS.enums.FormErrorType.UNSPECIFIED, formItem.name);
        }
      }

      window.getDate = function (formItemName) {
        var date = functions.getValues()[`${formItemName}`];
        return date == null ? null : new Date(new Date(date).setHours(0, 0, 0, 0));
      }

      window.checkDate = function (formItemName, formItemNameBegin, errorText) {
        var formItemValue = functions.getValues()[`${formItemName}`];
        if (formItemValue != null) {
          var today = new Date().setHours(0, 0, 0, 0);
          var date = window.getDate(formItemName);
          var beginDate = window.getDate(formItemNameBegin);
          functions.removeError(window[`errorDate${formItemName}`]);
          if ((date.getTime() < today) || (beginDate != null && date.getTime() < beginDate.getTime())) {
            window[`errorDate${formItemName}`] = functions.showError(errorText, undefined, ESS.enums.FormErrorType.UNSPECIFIED, formItemName);
          }
        }
      }
      
      window.getSubstitutionDataFromStorage = function() {
        try {
          var storedData = localStorage.getItem('NNSubstitutionSetup_Data');
          
          if (!storedData || storedData === '' || storedData === 'null') {
            console.log('[getSubstitutionDataFromStorage] No data in localStorage');
            return null;
          }
          
          var data = JSON.parse(storedData);
          
          if (!data.SubstituteIdsString || data.SubstituteIdsString === '') {
            console.log('[getSubstitutionDataFromStorage] No substitute IDs');
            return null;
          }
          
          var result = {
            substituteIds: data.SubstituteIdsString.split(';').filter(function(id) { return id && id !== ''; }),
            substituteNames: data.SubstituteNamesString ? data.SubstituteNamesString.split(';') : [],
            systemIds: data.SystemIdsString.split(';').filter(function(id) { return id && id !== ''; }),
            systemNames: data.SystemNamesString ? data.SystemNamesString.split(';') : [],
            startDates: data.StartDatesString.split(';').filter(function(date) { return date && date !== ''; }),
            endDates: data.EndDatesString.split(';').filter(function(date) { return date && date !== ''; })
          };
          
          console.log('[getSubstitutionDataFromStorage] Data loaded:', result.substituteIds.length, 'substitutes');
          return result;
        }
        catch (e) {
          console.error('[getSubstitutionDataFromStorage] Parse error:', e);
          return null;
        }
      };

      window.showSubstitutionInfo = function() {
        var data = window.getSubstitutionDataFromStorage();
        
        if (!data || data.substituteIds.length === 0) {
          console.log('[showSubstitutionInfo] No data to display');
          functions.setIsItemHidden('SubstitutionsInfoBlock', true);
          functions.setIsItemHidden('ShowSubstitutesButton', true);
          functions.setValue('SubstitutionsInfo', '');
          return false;
        }
        
        var infoText = ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_HEADER')) + '<br/><br/>';
        
        for (var i = 0; i < data.substituteIds.length; i++) {
          var startDate = data.startDates[i] ? new Date(data.startDates[i]).toLocaleDateString('ru-RU') : '?';
          var endDate = data.endDates[i] ? new Date(data.endDates[i]).toLocaleDateString('ru-RU') : '?';
          var subName = data.substituteNames[i];
          var sysName = data.systemNames[i];
          
          infoText += ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_ITEM_TEMPLATE'),(i + 1), subName, sysName , startDate, endDate) + '<br/>';
        }
        
        functions.setValue('SubstitutionsInfo', infoText);
        functions.setIsItemHidden('SubstitutionsInfoBlock', false);
        functions.setIsItemHidden('ShowSubstitutesButton', false);
        
        console.log('[showSubstitutionInfo] Info displayed');
        return true;
      };

      window.prepareSubstitutionParameters = function() {
        var data = window.getSubstitutionDataFromStorage();
        
        if (!data || data.substituteIds.length === 0) {
          console.log('[prepareSubstitutionParameters] No data to prepare');
          
          functions.setValue('SubstituteIdsString', '');
          functions.setValue('SystemIdsString', '');
          functions.setValue('StartDatesString', '');
          functions.setValue('EndDatesString', '');
          
          return false;
        }
        
        functions.setValue('SubstituteIdsString', data.substituteIds.join(';'));
        functions.setValue('SystemIdsString', data.systemIds.join(';'));
        functions.setValue('StartDatesString', data.startDates.join(';'));
        functions.setValue('EndDatesString', data.endDates.join(';'));
        
        console.log('[prepareSubstitutionParameters] Parameters set:', data.substituteIds.length, 'substitutes');
        return true;
      };

facility.beforeSubmitEventHandler:
    window.prepareSubstitutionParameters();
    
    var initiatorId = functions.getValues().Initiator;
    var vacationTypeId = functions.getValues().VacationTypeCurrent;
    var dayCountCompensation = functions.getValues().DayCountCompensation;
    var currentVacationData = functions.getValues().CurrentVacationData;
    functions.setValue('Field_Дней компенсации', dayCountCompensation);

    var durationRecall = functions.getValues().DurationRecall;
    functions.setValue('Field_Дней отзыва', durationRecall);
    var beginDateRecall = functions.getValues().BeginDateRecall;
    var endDateRecall = functions.getValues().EndDateRecall;
    var datesRecall = [];
    datesRecall.push(beginDateRecall);
    datesRecall.push(endDateRecall);
    var getFormatDatesRecall = ESS.network.sendRequest(`/api/functions/GetFormatDates?employeeId=${initiatorId}&dates=%5B${datesRecall}%5D`)
    .then(function (dates) {
      functions.setValue('Field_Дата начала части отпуска', dates[0]);
      functions.setValue('Field_Дата окончания части отпуска', dates[1]);
    });
    
    var durationShift = functions.getValues().DurationShift;
    functions.setValue('Field_Дней переноса', durationShift);
    var beginDateShift = functions.getValues().BeginDateShift;
    var endDateShift = functions.getValues().EndDateShift;
    var datesShift = [];
    datesShift.push(beginDateShift);
    datesShift.push(endDateShift);
    var getFormatDatesShift = ESS.network.sendRequest(`/api/functions/GetFormatDates?employeeId=${initiatorId}&dates=%5B${datesShift}%5D`)
    .then(function (dates) {
      functions.setValue('Field_Дата_начала_отпуска', dates[0]);
      functions.setValue('Field_Дата_окончания_отпуска', dates[1]);
    });

    var validateVacationData = ESS.scripts.HRProVacations.validateRecallVacationData({ functions, initiatorId, statementId: 0, vacationTypeId, beginDateRecall, endDateRecall, durationRecall, beginDateShift, endDateShift, durationShift, dayCountCompensation, currentVacationData });
    
    var validateSubstitutionDates = function() {
      var substitutionsInfo = functions.getValues().SubstitutionsInfo;
      
      if (!substitutionsInfo || substitutionsInfo === '' || substitutionsInfo === 'null') {
        return Promise.resolve({ isValid: true, errors: [] });
      }
      
      var vacationPeriodsJson = '';
      if (beginDateShift && endDateShift) {
        var periods = [{ StartDate: beginDateShift, EndDate: endDateShift }];
        vacationPeriodsJson = JSON.stringify(periods);
      }
      
      return ESS.scripts.HRProVacations.validateSubstitutionDates({ VacationPeriodsJson: vacationPeriodsJson, StartDatesString: functions.getValues().StartDatesString || '', EndDatesString: functions.getValues().EndDatesString || '', IsCallingService: true });
    };

    Promise.all([getFormatDatesRecall, getFormatDatesShift, validateVacationData, validateSubstitutionDates()])
    .then(function(results) {
      var substitutionResult = results[3];
      if (substitutionResult && !substitutionResult.isValid) {
        if (substitutionResult.errors && substitutionResult.errors.length > 0) {
        ESS.toasts.showToast(substitutionResult.errors[0].message, 'danger', true);
      }
        reject();
        return;
      }
      resolve();
    })
    .catch(function(error) {
      reject();
    });
